INSERT INTO `glossary_term` (`keyword`, `definition`, `updatedAt`) VALUES
  ('resolution', 'A measure one chamber votes on alone, usually about its own rules or opinions. It doesn''t become law.', CURRENT_TIMESTAMP(3)),
  ('joint resolution', 'Works much like a bill: it can become law. Proposed constitutional amendments use this form too, and those go to the states instead of the President.', CURRENT_TIMESTAMP(3)),
  ('concurrent resolution', 'Passed by both chambers, but it isn''t a law and doesn''t go to the President. Congress uses it for its own business, like budget plans.', CURRENT_TIMESTAMP(3)),
  ('sponsor', 'The member who formally introduced the bill.', CURRENT_TIMESTAMP(3)),
  ('cosponsor', 'A member who adds their name to show they support a bill. It isn''t a vote.', CURRENT_TIMESTAMP(3)),
  ('committee', 'A smaller group of members that studies bills on one subject. Most bills never get past this stage.', CURRENT_TIMESTAMP(3)),
  ('markup', 'The meeting where a committee debates a bill and changes its wording.', CURRENT_TIMESTAMP(3)),
  ('suspension of the rules', 'A fast track in the House: debate is limited to 40 minutes, no amendments are allowed, and it takes two-thirds to pass.', CURRENT_TIMESTAMP(3)),
  ('previous question', 'A House vote to end debate and move to a final vote. It''s procedural, so it isn''t a vote on the bill itself.', CURRENT_TIMESTAMP(3)),
  ('motion to recommit', 'A last attempt to send a bill back to committee, usually by the minority party. Often it''s a way to force a vote on a change.', CURRENT_TIMESTAMP(3)),
  ('cloture', 'How the Senate ends debate. It takes 60 votes for most matters.', CURRENT_TIMESTAMP(3)),
  ('filibuster', 'Using the Senate''s long debate rules to delay or block a vote. Ending it requires cloture.', CURRENT_TIMESTAMP(3)),
  ('unanimous consent', 'Passing something with no recorded vote, because no member present objects.', CURRENT_TIMESTAMP(3)),
  ('voice vote', 'Members call out yes or no together, and whoever is presiding decides which side won. No one''s vote is recorded.', CURRENT_TIMESTAMP(3)),
  ('roll call', 'A vote where each member''s position is recorded.', CURRENT_TIMESTAMP(3)),
  ('quorum', 'The minimum number of members who must be present to do business, usually a majority.', CURRENT_TIMESTAMP(3)),
  ('amendment', 'A proposed change to a bill''s text. A vote on an amendment isn''t a vote on the whole bill.', CURRENT_TIMESTAMP(3)),
  ('engrossed', 'The official copy of a bill after one chamber passes it.', CURRENT_TIMESTAMP(3)),
  ('enrolled', 'The final version, after both chambers pass the same text. It''s the copy sent to the President.', CURRENT_TIMESTAMP(3)),
  ('concur', 'To agree. When one chamber changes a bill, the other can concur and accept those changes.', CURRENT_TIMESTAMP(3)),
  ('conference report', 'A compromise version worked out by members of both chambers when they''ve passed different text.', CURRENT_TIMESTAMP(3)),
  ('veto', 'When the President rejects a bill. Congress can override it with a two-thirds vote in both chambers.', CURRENT_TIMESTAMP(3)),
  ('pocket veto', 'When the President doesn''t sign a bill and Congress has adjourned, so it dies without a formal veto.', CURRENT_TIMESTAMP(3)),
  ('public law', 'A bill that has become law. 119-87 means the 87th law of the 119th Congress.', CURRENT_TIMESTAMP(3)),
  ('appropriations', 'Money Congress sets aside for the government to spend, usually for one year.', CURRENT_TIMESTAMP(3)),
  ('authorization', 'A law that creates or continues a program and says how much it may spend. The money itself comes in a separate appropriation.', CURRENT_TIMESTAMP(3)),
  ('fiscal year', 'The government''s budget year. The federal one runs from October 1 to September 30.', CURRENT_TIMESTAMP(3)),
  ('FY', 'Fiscal year: the government''s budget year, which runs from October 1 to September 30.', CURRENT_TIMESTAMP(3)),
  ('mandatory spending', 'Spending set by existing law, like Social Security, that happens without a yearly vote.', CURRENT_TIMESTAMP(3)),
  ('discretionary spending', 'Spending Congress decides on each year through appropriations.', CURRENT_TIMESTAMP(3)),
  ('rescission', 'Canceling money that was already set aside, before it''s spent.', CURRENT_TIMESTAMP(3)),
  ('sunset', 'A date when a law or program ends unless Congress renews it.', CURRENT_TIMESTAMP(3)),
  ('block grant', 'Money sent to states in one lump sum for a broad purpose, with the details left to them.', CURRENT_TIMESTAMP(3)),
  ('statute', 'A written law passed by a legislature.', CURRENT_TIMESTAMP(3)),
  ('rulemaking', 'How a federal agency writes regulations that carry out a law.', CURRENT_TIMESTAMP(3)),
  ('jurisdiction', 'Who is in charge of something: which committee handles a bill, or which court can hear a case.', CURRENT_TIMESTAMP(3)),
  ('pursuant to', 'Following, or as required by.', CURRENT_TIMESTAMP(3)),
  ('notwithstanding', 'Even though, or regardless of. It lets a new law override an older one.', CURRENT_TIMESTAMP(3)),
  ('shall', 'Must. In a law, "shall" is a requirement, while "may" allows something without requiring it.', CURRENT_TIMESTAMP(3)),
  ('U.S.C.', 'The United States Code: every federal law currently in force, organized by subject.', CURRENT_TIMESTAMP(3)),
  ('CBO', 'The Congressional Budget Office, which estimates what bills would cost. It doesn''t take sides.', CURRENT_TIMESTAMP(3)),
  ('GAO', 'The Government Accountability Office, which checks how federal money is spent for Congress.', CURRENT_TIMESTAMP(3)),
  ('OMB', 'The Office of Management and Budget, which prepares the President''s budget and reviews regulations.', CURRENT_TIMESTAMP(3)),
  ('CRS', 'The Congressional Research Service, Congress''s nonpartisan research staff. It writes the bill summaries.', CURRENT_TIMESTAMP(3)),
  ('CRA', 'The Congressional Review Act, which lets Congress cancel a new federal regulation with a simple majority.', CURRENT_TIMESTAMP(3)),
  ('CRA', 'The Community Reinvestment Act, which asks banks to serve the communities where they take deposits.', CURRENT_TIMESTAMP(3)),
  ('SNAP', 'The Supplemental Nutrition Assistance Program, once called food stamps.', CURRENT_TIMESTAMP(3)),
  ('HHS', 'The Department of Health and Human Services.', CURRENT_TIMESTAMP(3)),
  ('DHS', 'The Department of Homeland Security.', CURRENT_TIMESTAMP(3)),
  ('DOD', 'The Department of Defense.', CURRENT_TIMESTAMP(3)),
  ('EPA', 'The Environmental Protection Agency.', CURRENT_TIMESTAMP(3)),
  ('NDAA', 'The National Defense Authorization Act, the yearly law that sets military policy and spending limits.', CURRENT_TIMESTAMP(3)),
  ('PAYGO', 'Pay-as-you-go: a rule that new spending or tax cuts must be paid for, so they don''t add to the deficit.', CURRENT_TIMESTAMP(3)),
  ('deficit', 'When the government spends more than it takes in during one year.', CURRENT_TIMESTAMP(3)),
  ('earmark', 'Money in a bill set aside for a specific project, often in one member''s district.', CURRENT_TIMESTAMP(3));
